using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using UnityEngine.Rendering;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

// Editor-only authoring source outside Assets. No runtime component is added.
public static class C01WayfindingApply {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B5/";
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 static Transform root,room,group;static JObject plan;static Vector3 origin;
 static Dictionary<string,Material> paints=new Dictionary<string,Material>();
 static List<string> generated=new List<string>();

 class Geometry {
  public List<Vector3> vertices=new List<Vector3>();public List<int> triangles=new List<int>();public List<Vector2> uv=new List<Vector2>();
  public void Quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d,float v0=0,float v1=1){int k=vertices.Count;vertices.AddRange(new[]{a,b,c,d});uv.AddRange(new[]{new Vector2(0,v0),new Vector2(1,v0),new Vector2(0,v1),new Vector2(1,v1)});triangles.AddRange(new[]{k,k+2,k+1,k+1,k+2,k+3});}
  public void FloorRect(Vector3 center,Vector3 forward,float width,float length){var right=Vector3.Cross(Vector3.up,forward).normalized*width*.5f;var along=forward.normalized*length*.5f;Quad(OnFloor(center-right-along),OnFloor(center+right-along),OnFloor(center-right+along),OnFloor(center+right+along));}
  public void Ribbon(Vector3[] points,float width,float offset){float distance=0;int first=vertices.Count;for(int i=0;i<points.Length;i++){Vector3 a=(points[i]-points[Math.Max(0,i-1)]).normalized,b=(points[Math.Min(points.Length-1,i+1)]-points[i]).normalized;var d=(a+b).normalized;if(d==Vector3.zero)d=i==0?b:a;var right=Vector3.Cross(Vector3.up,d);float correction=Mathf.Max(.6f,Vector3.Dot(right,Vector3.Cross(Vector3.up,i==0?b:a)));if(i>0)distance+=Vector3.Distance(points[i],points[i-1]);vertices.Add(OnFloor(points[i]+right*((offset-width*.5f)/correction)));vertices.Add(OnFloor(points[i]+right*((offset+width*.5f)/correction)));uv.Add(new Vector2(0,distance/.5f));uv.Add(new Vector2(1,distance/.5f));if(i>0){int k=first+i*2;triangles.AddRange(new[]{k-2,k,k-1,k-1,k,k+1});}}}
 }
 static Vector3 V(JToken p)=>new Vector3((float)p[0],0,(float)p[1]);
 static Vector3 OnFloor(Vector3 p){var world=origin+p;var hits=Physics.RaycastAll(world+Vector3.up*.32f,Vector3.down,.70f,~0,QueryTriggerInteraction.Ignore).Where(h=>h.normal.y>.85f&&h.collider.transform.IsChildOf(root)).OrderByDescending(h=>h.point.y).ToArray();if(hits.Length==0)throw new Exception("Missing floor at "+world);float top=hits[0].point.y;var finish=room.Find("S1_FloorFinish_02").GetComponent<Renderer>();if(new Vector2(p.x,p.z).magnitude<9.95f)top=Mathf.Max(top,finish.bounds.max.y);p.y=top-origin.y+.0025f;return p;}
 static GameObject Child(string name,Transform parent){var g=new GameObject(name);g.transform.SetParent(parent,false);return g;}
 static Material Material(string name,Color color,string texture=null,bool cutout=false){string path=E+"Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.name=name;m.SetColor("_BaseColor",color);m.SetFloat("_Metallic",0);m.SetFloat("_Smoothness",.18f);m.SetFloat("_SpecularHighlights",0);m.DisableKeyword("_EMISSION");m.SetColor("_EmissionColor",Color.black);m.globalIlluminationFlags=MaterialGlobalIlluminationFlags.EmissiveIsBlack;if(texture!=null){m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/"+texture+".png"));}if(cutout){m.SetFloat("_AlphaClip",1);m.SetFloat("_Cutoff",.35f);m.EnableKeyword("_ALPHATEST_ON");m.SetOverrideTag("RenderType","TransparentCutout");m.renderQueue=2450;}EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);generated.Add(path);return m;}
 static Mesh SaveMesh(string name,Geometry data){if(data.vertices.Count==0)throw new Exception("Empty geometry "+name);string path=E+name+".asset";var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);bool create=!m;if(create)m=new Mesh{name=name};else m.Clear();m.SetVertices(data.vertices);m.SetUVs(0,data.uv);m.SetTriangles(data.triangles,0);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();m.UploadMeshData(false);if(create)AssetDatabase.CreateAsset(m,path);else{EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);}generated.Add(path);return m;}
 static GameObject Add(string name,Geometry data,Material mat,Transform parent=null){var go=Child(name,parent?parent:group);go.AddComponent<MeshFilter>().sharedMesh=SaveMesh(name,data);var rr=go.AddComponent<MeshRenderer>();rr.sharedMaterial=mat;rr.shadowCastingMode=ShadowCastingMode.Off;rr.receiveShadows=true;rr.lightProbeUsage=LightProbeUsage.Off;rr.reflectionProbeUsage=ReflectionProbeUsage.Off;return go;}
 static Vector3[] Subdivide(Vector3[] p){var result=new List<Vector3>{p[0]};for(int i=1;i<p.Length;i++){int n=Mathf.CeilToInt(Vector3.Distance(p[i-1],p[i])/.16f);for(int j=1;j<=n;j++)result.Add(Vector3.Lerp(p[i-1],p[i],(float)j/n));}return result.ToArray();}
 static void Square(Geometry g,Vector3 center,Vector3 forward,float size,float stroke){var right=Vector3.Cross(Vector3.up,forward);g.FloorRect(center+right*(size-stroke)*.5f,forward,stroke,size);g.FloorRect(center-right*(size-stroke)*.5f,forward,stroke,size);g.FloorRect(center+forward*(size-stroke)*.5f,right,stroke,size-2*stroke);g.FloorRect(center-forward*(size-stroke)*.5f,right,stroke,size-2*stroke);}
 static Geometry BeveledPlate(){var g=new Geometry();int steps=6;var rings=new List<Vector3[]>();foreach(var spec in new[]{new Vector2(.003f,-.004f),new Vector2(0,0),new Vector2(.003f,.004f)}){var pts=new List<Vector3>();float w=.24f-spec.x*2,h=.36f-spec.x*2,r=.018f;for(int corner=0;corner<4;corner++){float cx=corner==0||corner==3?w*.5f-r:-w*.5f+r;float cy=corner<2?h*.5f-r:-h*.5f+r;for(int j=0;j<=steps;j++){float a=(corner*90+j*90f/steps)*Mathf.Deg2Rad;pts.Add(new Vector3(cx+Mathf.Cos(a)*r,cy+Mathf.Sin(a)*r,spec.y));}}rings.Add(pts.ToArray());}int n=rings[0].Length;for(int k=0;k<2;k++)for(int i=0;i<n;i++){int j=(i+1)%n;g.Quad(rings[k][j],rings[k][i],rings[k+1][j],rings[k+1][i]);}int start=g.vertices.Count;g.vertices.Add(Vector3.forward*.004f);g.uv.Add(Vector2.one*.5f);foreach(var p in rings[2]){g.vertices.Add(p);g.uv.Add(new Vector2(p.x/.24f+.5f,p.y/.36f+.5f));}for(int i=0;i<n;i++)g.triangles.AddRange(new[]{start,start+1+i,start+1+(i+1)%n});return g;}

 public static object Run(){
  var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Saved B5 edit scene required");
  root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;room=root.Find("C01_Experiment_Art");origin=room.position;plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/C01_Wayfinding/plan.json"));generated.Clear();paints.Clear();Physics.SyncTransforms();
  // Import only this task's new textures. Existing material assets are never saved globally.
  foreach(var file in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Environment/B5/Textures"),"CW_*.png")){string path=E+"Textures/"+Path.GetFileName(file);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.alphaIsTransparency=!path.Contains("Paint_Base");ti.mipmapEnabled=true;ti.filterMode=FilterMode.Trilinear;ti.wrapMode=path.Contains("Paint_Base")?TextureWrapMode.Repeat:TextureWrapMode.Clamp;ti.textureCompression=TextureImporterCompression.Uncompressed;ti.maxTextureSize=1024;ti.SaveAndReimport();}
  var previous=room.Find("C01_Workplace_Wayfinding");if(previous)UnityEngine.Object.DestroyImmediate(previous.gameObject);group=Child("C01_Workplace_Wayfinding",room).transform;Undo.RegisterCreatedObjectUndo(group.gameObject,"C01 floor guidance and portal codes");
  foreach(var route in plan["routes"]){string code=(string)route["id"];Color col;ColorUtility.TryParseHtmlString((string)route["color"],out col);paints[code]=Material("CW_Paint_"+code,col,"CW_Paint_Base");var p=route["points"].Select(V).ToArray();var g=new Geometry();string kind=(string)route["kind"];float width=(float)route["width"];
   if(kind=="double"){var smooth=Subdivide(p);g.Ribbon(smooth,width,-.12f);g.Ribbon(smooth,width,.12f);}else if(kind=="single")g.Ribbon(Subdivide(p),width,0);else {var delta=p[1]-p[0];float len=delta.magnitude;for(float t=0;t<len;t+=.41f)g.Ribbon(Subdivide(new[]{p[0]+delta.normalized*t,p[0]+delta.normalized*Mathf.Min(t+.25f,len)}),width,0);}
   if(code=="R1"){var join=new Vector3(-.2f,0,5.6f);for(int i=0;i<g.vertices.Count;i++){var v=g.vertices[i];float planar=Vector2.Distance(new Vector2(v.x,v.z),new Vector2(join.x,join.z));v.y=Mathf.Lerp(v.y,.018f,Mathf.Clamp01((.45f-planar)/.28f));g.vertices[i]=v;}}
   Add("CW_"+code+"_FloorRoute",g,paints[code]);
   if(code=="S1"){var marks=new Geometry();float distance=0,next=1.5f;for(int i=1;i<p.Length;i++){float len=Vector3.Distance(p[i-1],p[i]);while(next<=distance+len){var direction=(p[i]-p[i-1]).normalized;var point=Vector3.Lerp(p[i-1],p[i],(next-distance)/len);Square(marks,point+Vector3.Cross(Vector3.up,direction)*.20f,direction,.20f,.035f);next+=2.7f;}distance+=len;}Add("CW_S1_SquareMarkers",marks,paints[code]);}
  }
  foreach(string code in new[]{"R1","S1","M1"}){var g=new Geometry();foreach(var label in plan["labels"].Where(l=>(string)l["code"]==code)){var f=V(label["forward"]).normalized;g.FloorRect(V(label["position"])+Vector3.Cross(Vector3.up,f)*(float)label["side"],f,.46f,.69f);}var mat=Material("CW_FloorCode_"+code,paints[code].GetColor("_BaseColor"),"CW_Floor_"+code,true);Add("CW_"+code+"_FloorCodes",g,mat);}
  var brackets=new Geometry();Vector3 mCenter=new Vector3(Mathf.Cos(152*Mathf.Deg2Rad),0,Mathf.Sin(152*Mathf.Deg2Rad))*7.25f;var mfwd=mCenter.normalized;var mr=Vector3.Cross(Vector3.up,mfwd);foreach(float side in new[]{-1f,1f}){brackets.FloorRect(mCenter+mr*.49f*side,mfwd,.035f,.58f);brackets.FloorRect(mCenter+mr*.36f*side-mfwd*.2725f,mr,.035f,.30f);}Add("CW_M1_ServiceAccess",brackets,paints["M1"]);
  var baseMat=Material("CW_PlateBase",new Color(.055f,.075f,.08f));var plateMesh=SaveMesh("CW_PortalCodePlate",BeveledPlate());
  foreach(var item in plan["doors"]){string id=(string)item["id"],code=(string)item["code"];var portal=root.Find("Pocket_Doors_Open/"+id+"/Clinical_Portal");if(!portal)throw new Exception("Missing portal "+id);var corners=new Geometry();foreach(float side in new[]{-1f,1f})foreach(float face in new[]{-1f,1f}){var p=portal.TransformPoint(new Vector3(side*.98f,0,face*.62f))-origin;corners.FloorRect(p,portal.forward,.04f,.38f);corners.FloorRect(p-portal.right*side*.12f+portal.forward*face*.17f,portal.right,.04f,.28f);}Add("CW_Threshold_"+id,corners,paints[code]);
   var mount=Child("PortalCode_"+id,group).transform;var mountingRay=new Ray(portal.TransformPoint(new Vector3(-1.48f,1.50f,-1.2f)),portal.forward);var frameHits=Physics.RaycastAll(mountingRay,2.4f,~0,QueryTriggerInteraction.Ignore).Where(h=>h.collider.transform.IsChildOf(portal)&&h.collider.name.Contains("Frame")).OrderBy(h=>h.distance).ToArray();if(frameHits.Length==0)throw new Exception("Plate has no supporting frame "+id);mount.position=frameHits[0].point-portal.forward*.0045f;mount.rotation=portal.rotation*Quaternion.Euler(0,180,0);var body=Child("Beveled_Plate",mount);body.AddComponent<MeshFilter>().sharedMesh=plateMesh;var br=body.AddComponent<MeshRenderer>();br.sharedMaterial=baseMat;br.shadowCastingMode=ShadowCastingMode.Off;
   var faceGeo=new Geometry();faceGeo.Quad(new Vector3(-.106f,-.159f,.0046f),new Vector3(.106f,-.159f,.0046f),new Vector3(-.106f,.159f,.0046f),new Vector3(.106f,.159f,.0046f));for(int i=0;i<faceGeo.triangles.Count;i+=3){int n=faceGeo.triangles[i+1];faceGeo.triangles[i+1]=faceGeo.triangles[i+2];faceGeo.triangles[i+2]=n;}for(int i=0;i<faceGeo.uv.Count;i++)faceGeo.uv[i]=new Vector2(1-faceGeo.uv[i].x,faceGeo.uv[i].y);var ink=Material("CW_PlateCode_"+code,paints[code].GetColor("_BaseColor"),"CW_Plate_"+code,true);Add("CW_Face_"+id,faceGeo,ink,mount);
  }
  EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);
  var result=new{scene=s.path,routes=3,floorCodeStencils=plan["labels"].Count(),portalCodes=3,newColliders=group.GetComponentsInChildren<Collider>().Length,generated=generated.Distinct().ToArray(),existingR1Preserved=true,lightingUnchanged=true};File.WriteAllText(Repo+"/Docs/검수/2026-11-07_C01_Wayfinding/apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
}
